/* ============================================
   COMPOSER COMPONENT
   The chat input shell: file tray, auto-growing textarea, send/stop
   ============================================ */

/* The focus treatment animates a registered custom property, exactly as
   AiButton does: a conic gradient's angle cannot tween otherwise. Browsers
   without @property render the ring at its initial angle, static — a
   correct, quieter fallback. Registered under its own name so Composer
   never depends on AiButton's stylesheet being loaded. */
@property --ds-composer-glow-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

.ds-composer {
  /* Anchors the focus ring and glow pseudo-elements */
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  /* The send button's diameter — CircularButton's default size, which is
     a raw value in CircularButton.css too (icon-button sizes are not on
     a token scale). Everything concentric derives from it. */
  --ds-composer-send-size: 40px;
  /* The shell's concentric corner, derived rather than frozen: the send
     button's EFFECTIVE radius (its --radius-pill capped at half its own
     size — 999px never renders rounder than a circle), plus the action
     bar's padding-200 ring, plus the border width (border-radius applies
     to the border's outer edge). Shipped theme: min(999, 20) + 8 + 1 =
     the historical 29px. A theme that squares the pill (radiusOverrides'
     pill branch, the crisp presets) flows straight through, so the shell
     always sits concentric with whatever button it wraps. Component-local
     by design — one component's geometry, not a step on the global radius
     scale (design.md's Composer section owns the contract). */
  --ds-composer-radius: calc(
    min(var(--radius-pill), var(--ds-composer-send-size) / 2) +
      var(--padding-200) + var(--border-025)
  );
  background-color: var(--color-input-bg-primary);
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--ds-composer-radius);
  box-shadow: var(--shadow-floating);
  transition: border-color var(--motion-duration-fast) var(--motion-ease-standard);
  /* The whole shell is the input affordance — clicking anywhere that is
     not a control focuses the textarea, and the cursor says so. The
     action bar below opts back out. */
  cursor: text;
}

/* The shell carries the input focus/hover treatment — the textarea inside
   is borderless, so the whole surface reads as one control */
.ds-composer:hover:not(:focus-within) {
  border-color: var(--color-input-border-hover);
}

.ds-composer:focus-within {
  border-color: var(--color-input-border-selected);
}

/* ============================================
   AI GLOW — opt-in via the `aiGlow` prop
   While focused, the plain selected border stands down and the AI gradient
   ring takes its place — the same "a model answers here" signal AiButton
   carries, for composers whose messages are answered by a model.
   ============================================ */

.ds-composer--ai-glow:focus-within {
  border-color: transparent;
}

/* The gradient ring: AiButton's treatment on the composer shell — a conic
   gradient painted across the whole box, masked to the border band (two
   fills, exclude-composited, inset by the border width). The gradient
   repeats back to its start colour so the seam at 360° is invisible while
   it turns. Negative inset lays the pseudo over the shell's own border
   box, so the ring replaces the border exactly. */
.ds-composer--ai-glow::before {
  content: '';
  position: absolute;
  inset: calc(-1 * var(--border-025));
  border-radius: inherit;
  /* One step up from the shell's --border-025 border: the outer edge stays on
     the border box and the extra pixel grows inward, so the thicker band
     reads clearly on low-density screens without changing the geometry. */
  padding: var(--border-050);
  background: conic-gradient(
    from var(--ds-composer-glow-angle),
    var(--color-ai-gradient-start),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-end),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-start)
  );
  /* Standard properties only — the build pipeline prefixes per its browser
     targets, and hand-written -webkit- duplicates confuse its merging. */
  /* ds-allow(color): mask luminance keying — the #fff paints alpha coverage
     for mask-composite, not a theme colour */
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
  /* ds-allow(motion): ambient signature rotation, matched to AiButton's —
     deliberately far slower than the interaction-scale motion tokens; the
     21s loop is AiButton's three-uneven-turns cadence */
  animation: ds-composer-glow-turn 21s var(--motion-ease-emphasized) infinite paused;
}

/* The glow: the same gradient, blurred behind the opaque shell at low
   opacity, so it reads as a halo around the border. A colour effect, not
   an elevation shadow — depth stays token-owned. */
.ds-composer--ai-glow::after {
  content: '';
  position: absolute;
  inset: calc(-1 * var(--border-025));
  border-radius: inherit;
  background: conic-gradient(
    from var(--ds-composer-glow-angle),
    var(--color-ai-gradient-start),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-end),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-start)
  );
  /* The glow's spread; a length with no token family, matched to AiButton. */
  --ds-composer-glow: 14px;
  filter: blur(var(--ds-composer-glow));
  opacity: 0;
  /* Resting, the glow waits collapsed at the send-button corner (fractions
     chosen by eye, matching AiButton's entry) — waking is a bloom out of
     that corner, not a flat fade. This rest-state transition is the way
     back: losing focus collapses the halo quickly on the base pace. */
  transform-origin: 95% 85%;
  transform: scale(0.35);
  z-index: -1;
  pointer-events: none;
  transition:
    opacity var(--motion-duration-base) var(--motion-ease-standard),
    transform var(--motion-duration-base) var(--motion-ease-standard);
  /* ds-allow(motion): same ambient rotation as the ring, kept in phase */
  animation: ds-composer-glow-turn 21s var(--motion-ease-emphasized) infinite paused;
}

/* Waking: the entry. The glow blooms out of the send-button corner over
   the entrance pace and the ring fades up a --motion-duration-fast beat
   behind it — the transition here (the destination state's) governs the
   way in; the resting rules above govern the quick way back. */
.ds-composer--ai-glow:focus-within::before {
  opacity: 1;
  transition: opacity var(--motion-duration-slower) var(--motion-ease-entrance) var(--motion-duration-fast);
  animation-play-state: running;
}

.ds-composer--ai-glow:focus-within::after {
  opacity: 0.3;
  transform: none;
  transition:
    opacity var(--motion-duration-slower) var(--motion-ease-entrance),
    transform var(--motion-duration-slower) var(--motion-ease-entrance);
  animation-play-state: running;
}

/* AiButton's cadence, restated on the Composer-scoped angle: three uneven
   turns eased per segment, ending on a whole turn so the wrap is seamless
   and the average pace stays one turn per 7s. */
@keyframes ds-composer-glow-turn {
  0% {
    --ds-composer-glow-angle: 0deg;
  }
  14% {
    --ds-composer-glow-angle: 168deg;
  }
  31% {
    --ds-composer-glow-angle: 306deg;
  }
  46% {
    --ds-composer-glow-angle: 570deg;
  }
  62% {
    --ds-composer-glow-angle: 690deg;
  }
  79% {
    --ds-composer-glow-angle: 936deg;
  }
  100% {
    --ds-composer-glow-angle: 1080deg;
  }
}

/* Working: while a response streams, the ring stays lit and keeps turning
   whether or not the field holds focus — the visible half of the `streaming`
   contract for glowing composers. The pairing is defined in design.md's
   Composer section; streaming without aiGlow changes nothing. */
.ds-composer--ai-glow.ds-composer--streaming {
  border-color: transparent;
}

.ds-composer--ai-glow.ds-composer--streaming::before {
  opacity: 1;
  transition: opacity var(--motion-duration-slower) var(--motion-ease-entrance) var(--motion-duration-fast);
  animation-play-state: running;
}

.ds-composer--ai-glow.ds-composer--streaming::after {
  opacity: 0.3;
  transform: none;
  transition:
    opacity var(--motion-duration-slower) var(--motion-ease-entrance),
    transform var(--motion-duration-slower) var(--motion-ease-entrance);
  animation-play-state: running;
}

/* Reduced motion: the ring and glow stay, the turning stops. */
@media (prefers-reduced-motion: reduce) {
  .ds-composer--ai-glow::before,
  .ds-composer--ai-glow::after {
    animation: none;
  }
}

/* ============================================
   CONTEXT CHIP
   A full-width, non-interactive note — what the model is currently looking
   at. At the very top of the shell by default, or lifted above it as its
   own bar (contextPlacement="above", styled at the end of this section).
   Composer owns the chrome; the caller passes the text.
   ============================================ */

.ds-composer__context {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  /* The action bar's tight --padding-200 ring, open toward the text below */
  margin: var(--padding-200) var(--padding-200) 0;
  /* ModelPicker's trigger geometry — the send button's height with the same
     0/padding-md inset — so the chip and the bar's pills read as one family */
  height: var(--ds-composer-send-size);
  padding: 0 var(--padding-400);
  background-color: var(--color-chat-context-bg);
  /* A full pill, matching the suggestion chips around the composer */
  border-radius: var(--radius-pill);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  /* Tertiary, like DocumentChip's metadata line — the note is ambient
     context, quieter than anything a person typed. The icon inherits it:
     one tone for the whole note. */
  color: var(--color-text-tertiary);
  /* Not editable, not a control — but a click still falls through the shell
     handler and focuses the textarea */
  cursor: default;
}

.ds-composer__context-icon {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

.ds-composer__context-icon .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

/* ---------- contextPlacement="above" ----------
   The chip leaves the shell for its own bar, full width, a small gap clear
   of the shell's top edge, and the layout aligns on one optical rail: the
   bar's --padding-200 ring plus the --padding-400 pill inset (24px). The
   typed text, the attachments, the chip's icon ink and a ModelPicker
   trigger's label all start on it. The inside placement keeps its own
   geometry above, untouched. */

/* The bar and the shell travel as one block, so a host's gap never lands
   between them */
.ds-composer-group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200);
  width: 100%;
}

.ds-composer__context--above {
  margin: 0;
  /* Outside the shell, so the shell's custom properties do not reach it:
     the send button's raw 40px, restated */
  height: 40px;
  /* The rail, plus the shell border this bar does not sit inside */
  padding: 0 var(--padding-400) 0
    calc(var(--padding-200) + var(--padding-400) + var(--border-025));
}

/* Optical alignment: a glyph's ink starts inside its box, so the box is
   pulled back by that side bearing to land the ink on the rail. The
   default fits the portrait document glyphs a context note usually
   carries (ink starts 4/24 into the box); the fallback is a consumer hook
   for a glyph with a different bearing. */
.ds-composer__context--above .ds-composer__context-icon {
  margin-left: calc(-1 * var(--ds-composer-context-icon-bearing, var(--icon-size-500) * 4 / 24));
}

.ds-composer--context-above .ds-composer__attachments,
.ds-composer--context-above .ds-composer__content {
  padding-inline: calc(var(--padding-200) + var(--padding-400));
}

/* The text owns the truncation: one line, ellipsized only when the note
   actually outgrows the shell — an ellipsis is a truncation mark, not
   punctuation. The icon beside it never shrinks. */
.ds-composer__context-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ============================================
   FILE TRAY
   The queued files: one row of square tiles that scrolls sideways rather
   than growing the shell.
   ============================================ */

.ds-composer__tray {
  /* How far the tiles sit in from the shell's edge. The tile corner below
     is derived from it, so the two can only move together. */
  --ds-composer-tray-inset: var(--padding-300);
  /* Concentric with the shell: its radius, less the border, less the inset.
     Floored so a squared theme never computes a negative corner. */
  --ds-attachment-tile-radius: max(
    var(--radius-100),
    calc(var(--ds-composer-radius) - var(--border-025) - var(--ds-composer-tray-inset))
  );

  display: flex;
  /* A scroller may be squeezed by the column it sits in; the tray keeps
     its tiles' full height */
  flex: none;
  gap: var(--gap-200);
  margin: 0;
  /* The inset on every side but the foot, where the text zone's own top
     padding takes over and only a sliver is kept so the scrollbar of an
     overflowing row does not touch the tiles. The top inset also houses the part of a remove
     button that hangs above its tile: a scroller clips what leaves it. */
  padding: var(--ds-composer-tray-inset) var(--ds-composer-tray-inset) var(--padding-100);
  list-style: none;
  overflow-x: auto;
  /* Tiles are objects, not text: the shell's text cursor stops at them */
  cursor: default;
  scrollbar-width: thin;
  scrollbar-color: var(--color-bg-container-secondary) transparent;
}

.ds-composer__tray-item {
  display: flex;
  flex: none;
}

/* ============================================
   DROP HINT
   While files hover over the shell it says what letting go will do.
   ============================================ */

.ds-composer--dragging {
  border-color: var(--color-input-border-selected);
}

.ds-composer__drop-hint {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: inherit;
  background-color: var(--color-bg-container-primary-semi);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
  /* Never a target: the shell hears the drag, and a hint that caught the
     pointer would fire a leave on everything under it */
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-composer--dragging .ds-composer__drop-hint {
  opacity: 1;
}

/* The picker itself is never seen: the attach button opens it */
.ds-composer__file-input {
  display: none;
}

.ds-composer__sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================
   ATTACHMENTS ROW (legacy free-form slot)
   ============================================ */

.ds-composer__attachments {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--gap-100);
  /* Top ring only — the text zone below keeps its own full padding-md,
     so chips sit a clear padding-md above the first text line */
  padding: var(--padding-400) var(--padding-500) 0;
}

/* ============================================
   CONTENT ZONE
   The text zone breathes more than the action bar: generous top and
   inline padding, tighter toward the bar below it.
   ============================================ */

.ds-composer__content {
  display: flex;
  /* The textarea keeps its own natural height rather than stretching to the
     zone's — the measurement below reads it, so a stretched textarea would
     feed its own height back in and the zone could never shrink. */
  align-items: flex-start;
  box-sizing: border-box;
  width: 100%;
  padding: var(--padding-400) var(--padding-500) var(--padding-200);
  /* Growing and shrinking is animated, which needs two pixel heights to run
     between — `auto` has nothing to interpolate. So the zone states its own
     height: the measured textarea (published as --ds-composer-text-height on
     every resize) plus the block padding it owns. The fallback is a single
     row, which is what the shell renders before the first measurement. */
  height: calc(
    var(--ds-composer-text-height, var(--font-paragraph-line-height)) + var(--padding-400) +
      var(--padding-200)
  );
  /* Mid-transition the textarea is already at its new height, so the extra
     line is clipped on the way in and released on the way out. */
  overflow: hidden;
  transition: height var(--motion-duration-instant) var(--motion-ease-emphasized);
}

.ds-composer__textarea {
  width: 100%;
  padding: 0;
  border: none;
  outline: none;
  background-color: transparent;
  resize: none;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-input-text-primary);
  /* Growth cap: the shell owns the block padding, so the cap is rows × line-height.
     --ds-composer-max-rows is set inline from the maxRows prop. */
  max-height: calc(var(--ds-composer-max-rows, 8) * var(--font-paragraph-line-height));
  overflow-y: auto;
}

.ds-composer__textarea::placeholder {
  color: var(--color-input-text-placeholder);
}

/* Overflow scrollbar — thin, trackless, and quiet instead of the bulky
   platform default. scrollbar-* covers Firefox and modern Chromium;
   the -webkit rules cover Safari. */
.ds-composer__textarea {
  scrollbar-width: thin;
  scrollbar-color: var(--color-bg-container-secondary) transparent;
}

.ds-composer__textarea::-webkit-scrollbar {
  width: 6px;
}

.ds-composer__textarea::-webkit-scrollbar-track {
  background: transparent;
}

.ds-composer__textarea::-webkit-scrollbar-thumb {
  background-color: var(--color-bg-container-secondary);
  border-radius: var(--radius-pill);
}

/* Native auto-grow where supported; the JS measurement path stands down
   (it checks the same capability) */
@supports (field-sizing: content) {
  .ds-composer__textarea {
    field-sizing: content;
  }
}

/* ============================================
   FOOTER ROW
   ============================================ */

.ds-composer__footer {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  /* The tight uniform ring the concentric corner is computed from */
  padding: var(--padding-200);
  /* Empty bar space still focuses the textarea on click, but the bar is
     control territory, so it keeps the default cursor. */
  cursor: default;
}

.ds-composer__actions {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
}

.ds-composer__trailing {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  margin-left: auto;
}

/* ============================================
   DISABLED
   ============================================ */

.ds-composer--disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background-color: var(--color-input-bg-disabled);
}

.ds-composer--disabled:hover:not(:focus-within),
.ds-composer--disabled:focus-within {
  border-color: var(--color-input-border-disabled);
}

.ds-composer--disabled:focus-within::before,
.ds-composer--disabled:focus-within::after {
  opacity: 0;
  animation-play-state: paused;
}

.ds-composer--disabled .ds-composer__textarea {
  cursor: not-allowed;
  color: var(--color-input-text-disabled);
}

'use client';

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { AttachmentTile } from '../Attachment/AttachmentTile';
import { formatBytes } from '../Attachment/fileTypes';
import type { AttachmentItem } from '../Attachment/fileTypes';
import { CircularButton } from '../CircularButton/CircularButton';
import '../../fonts/material-symbols.css';
import './Composer.css';

/** Props owned by Composer itself — everything else falls through to the <textarea>. */
type ComposerOwnProps = {
  /** Current value for controlled use. Pair with `onValueChange`. */
  value?: string;
  /** Initial value for uncontrolled use. */
  defaultValue?: string;
  /**
   * Convenience callback receiving the value directly.
   * Fires alongside `onChange`, which keeps the standard React event signature
   * so form libraries work unmodified.
   */
  onValueChange?: (value: string) => void;
  /**
   * Fires with the current value on Enter (without Shift) and on the send
   * button — never while `streaming`, never while a file in `files` is
   * still uploading, and never when there is nothing to send. Text is
   * enough, and so is a ready file on its own, in which case the value is
   * an empty string. Composer does not clear the value: the consumer owns
   * it and clears it after a successful submit. Shadows the native
   * `onSubmit` attribute, which never fires on a textarea anyway.
   */
  onSubmit?: (value: string) => void;
  /**
   * A response is streaming: the send button becomes a stop button, submit
   * is blocked, and Enter is inert. On a glowing composer (`aiGlow`) the
   * gradient ring also stays lit and keeps turning while this is true.
   */
  streaming?: boolean;
  /** Fires when the stop button is pressed while `streaming`. */
  onStop?: () => void;
  /** Growth cap in text rows before the textarea scrolls internally. */
  maxRows?: number;
  /**
   * While focused, the shell wears AiButton's slowly rotating gradient ring
   * and glow in place of the plain selected border — the system's "a model
   * answers here" signal, for composers whose messages are answered by one.
   * While `streaming`, the ring stays lit and turning whether or not the
   * field holds focus. Off by default.
   */
  aiGlow?: boolean;
  /**
   * Contextual note rendered as a full-width, non-interactive chip — the
   * "what the model is looking at" line a chat host pins over the message
   * ("Looking at “Page name”"). `contextPlacement` decides where it sits.
   * One line: a note too long for the shell truncates with an ellipsis.
   * Composer owns the chip's chrome; the caller passes the text.
   */
  context?: React.ReactNode;
  /**
   * Where the `context` chip sits. `inside` (the default) pins it at the very
   * top of the shell, above any attachments. `above` lifts it out of the
   * shell into its own bar a small gap above it, so it reads as what the
   * model can see rather than part of the message being typed. Either way
   * its icon starts on the shell's text rail, and a click on it focuses the
   * textarea.
   */
  contextPlacement?: 'inside' | 'above';
  /**
   * Icon at the left of the context chip — Material Symbol name (string,
   * e.g. `visibility`, `article`) or custom element (ReactNode). Decorative
   * and hidden from assistive technology — the chip's text carries the
   * meaning. None by default, matching the ai set's icon-free-unless-asked
   * convention.
   */
  contextIcon?: string | React.ReactNode;
  /**
   * The files queued on this message, drawn as a scrolling row of square
   * tiles above the textarea. Controlled by the caller: Composer draws the
   * list and reports what was added or removed, and never stores a file.
   * `useAttachments` is the usual owner.
   */
  files?: AttachmentItem[];
  /**
   * Fires with the files a person picked, pasted or dropped. Providing it
   * arms all three: the attach button and its picker, file paste in the
   * textarea, and drop on the shell.
   */
  onFilesSelected?: (files: File[]) => void;
  /** Fires with the id of the file whose remove button was pressed. Its presence renders the buttons. */
  onFileRemove?: (id: string) => void;
  /** Fires with a queued file when its tile is pressed. Its presence makes the tiles buttons. */
  onFileClick?: (item: AttachmentItem) => void;
  /** File types the picker offers, in the native `accept` syntax. */
  accept?: string;
  /** Whether the picker allows several files at once. */
  multiple?: boolean;
  /** Whether the built-in attach button shows when `onFilesSelected` is set. */
  attachButton?: boolean;
  /**
   * Pasted text at least this many characters long becomes an attachment
   * instead of landing in the textarea. Off unless set, and inert without
   * `onPasteAsAttachment`.
   */
  pasteThreshold?: number;
  /** Receives pasted text that met `pasteThreshold`. */
  onPasteAsAttachment?: (text: string) => void;
  /** Accessible label for the attach button. */
  attachLabel?: string;
  /** Text shown on the shell while files are dragged over it. */
  dropLabel?: string;
  /** Accessible label for the list of queued files. */
  filesLabel?: string;
  /**
   * Builds the sentence announced to assistive technology when files join
   * the queue, leave it, or fail.
   */
  formatFileAnnouncement?: (change: {
    type: 'added' | 'removed' | 'failed';
    names: string[];
  }) => string;
  /**
   * Free-form row rendered above the textarea, after any `files`.
   *
   * @deprecated Use `files` with `onFilesSelected` and `onFileRemove`, which draw the queue as tiles.
   */
  attachments?: React.ReactNode;
  /** Leading actions on the left of the action bar, after the attach button (a model picker). */
  actions?: React.ReactNode;
  /**
   * Trailing actions on the right of the action bar, just before the send
   * button (dictation, voice mode).
   */
  trailingActions?: React.ReactNode;
  /** Accessible label for the send button. */
  sendLabel?: string;
  /** Accessible label for the stop button. */
  stopLabel?: string;
  /** Additional CSS classes — applied to the shell, not the <textarea>. */
  className?: string;
};

export interface ComposerProps
  extends ComposerOwnProps,
    Omit<React.ComponentPropsWithoutRef<'textarea'>, keyof ComposerOwnProps> {}

const defaultFileAnnouncement = ({
  type,
  names,
}: {
  type: 'added' | 'removed' | 'failed';
  names: string[];
}) => {
  const list = names.join(', ');
  if (type === 'added') return `Attached ${list}`;
  if (type === 'removed') return `Removed ${list}`;
  return `Could not attach ${list}`;
};

const dragCarriesFiles = (event: React.DragEvent) =>
  Array.from(event.dataTransfer?.types ?? []).includes('Files');

/**
 * Composer is the chat input shell: an optional context note ("Looking at
 * “Page name”"), a tray of queued files, an auto-growing textarea, a leading
 * actions slot, and a trailing send button — the one sanctioned
 * primary-action teal in the chat set, because sending a message is a
 * genuine primary CTA. While `streaming`, send becomes stop and Enter
 * is inert.
 *
 * The textarea grows with its content up to `maxRows`, then scrolls
 * internally. Where the browser supports `field-sizing: content` the sizing
 * is fully native; elsewhere a measurement effect keeps the height in step.
 * Either way the text zone glides between the two heights rather than
 * snapping — 75ms, short enough to soften the step without reading as an
 * animation. The action bar's buttons never move relative to the bar.
 *
 * Forwards a ref to the underlying `<textarea>` and spreads unrecognised
 * props onto it; `className` lands on the shell.
 */
export const Composer = React.forwardRef<HTMLTextAreaElement, ComposerProps>(
  (
    {
      value,
      defaultValue,
      onValueChange,
      onSubmit,
      streaming = false,
      onStop,
      maxRows = 8,
      aiGlow = false,
      context,
      contextIcon,
      contextPlacement = 'inside',
      files,
      onFilesSelected,
      onFileRemove,
      onFileClick,
      accept,
      multiple = true,
      attachButton = true,
      pasteThreshold,
      onPasteAsAttachment,
      attachLabel = 'Attach files',
      dropLabel = 'Drop files to attach',
      filesLabel = 'Attachments',
      formatFileAnnouncement = defaultFileAnnouncement,
      attachments,
      actions,
      trailingActions,
      sendLabel = 'Send message',
      stopLabel = 'Stop generating',
      className = '',
      onChange,
      onKeyDown,
      onPaste,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-composer';
    const textareaRef = useRef<HTMLTextAreaElement | null>(null);
    const contentRef = useRef<HTMLDivElement | null>(null);

    const isControlled = value !== undefined;
    const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? '');
    const currentValue = isControlled ? value : uncontrolledValue;

    const disabled = Boolean(rest.disabled);
    const queued = files ?? [];
    const hasFiles = queued.length > 0;
    const armed = Boolean(onFilesSelected);
    /* A message is text, files, or both. A file still uploading holds the
       send back: sending now would leave it behind. */
    const anyUploading = queued.some((file) => file.status === 'uploading');
    const anyReady = queued.some((file) => file.status === 'ready');
    const canSend = !disabled && !anyUploading && (currentValue.trim() !== '' || anyReady);

    const fileInputRef = useRef<HTMLInputElement | null>(null);
    const trayRef = useRef<HTMLUListElement | null>(null);
    const [dragging, setDragging] = useState(false);
    const dragDepth = useRef(0);
    const [announcement, setAnnouncement] = useState('');

    /** Keep the internal ref (used for auto-grow) while honouring a forwarded one. */
    const setTextareaRef = (node: HTMLTextAreaElement | null) => {
      textareaRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    useLayoutEffect(() => {
      const node = textareaRef.current;
      if (!node) return;
      // Native sizing takes over where supported — see the @supports block in the CSS.
      if (typeof CSS !== 'undefined' && CSS.supports('field-sizing', 'content')) return;
      node.style.height = 'auto';
      node.style.height = `${node.scrollHeight}px`;
    }, [currentValue]);

    /* The text zone animates between heights (see the transition in the CSS),
       which needs the measured height as a number rather than `auto`. A
       ResizeObserver publishes it on every cause at once: a wrapped or deleted
       line, a clear after send, and a rewrap when the shell changes width. */
    useLayoutEffect(() => {
      const node = textareaRef.current;
      const content = contentRef.current;
      if (!node || !content) return;
      const observer = new ResizeObserver(() => {
        content.style.setProperty('--ds-composer-text-height', `${node.offsetHeight}px`);
      });
      observer.observe(node);
      return () => observer.disconnect();
    }, []);

    /* Say what changed in the queue. The tiles appear and vanish silently
       for a screen-reader user otherwise: a paste or a drop moves no focus. */
    const previousFiles = useRef<AttachmentItem[]>(queued);
    const announceRef = useRef(formatFileAnnouncement);
    announceRef.current = formatFileAnnouncement;
    useEffect(() => {
      const before = previousFiles.current;
      const now = files ?? [];
      previousFiles.current = now;
      if (before === now) return;
      const beforeById = new Map(before.map((file) => [file.id, file]));
      const nowIds = new Set(now.map((file) => file.id));
      const added = now.filter((file) => !beforeById.has(file.id)).map((file) => file.name);
      const removed = before.filter((file) => !nowIds.has(file.id)).map((file) => file.name);
      const failed = now
        .filter((file) => file.status === 'error' && beforeById.get(file.id)?.status !== 'error')
        .map((file) => file.name);
      const parts = [
        failed.length > 0 ? announceRef.current({ type: 'failed', names: failed }) : '',
        added.length > 0 ? announceRef.current({ type: 'added', names: added }) : '',
        removed.length > 0 ? announceRef.current({ type: 'removed', names: removed }) : '',
      ].filter(Boolean);
      if (parts.length > 0) setAnnouncement(parts.join('. '));
    }, [files]);

    /* Removing the focused tile would drop focus to the document. It moves
       to the tile that took its place, or back to the textarea when the
       queue empties. */
    const focusAfterRemove = useRef<number | null>(null);
    useEffect(() => {
      const index = focusAfterRemove.current;
      if (index === null) return;
      focusAfterRemove.current = null;
      const buttons = trayRef.current?.querySelectorAll<HTMLButtonElement>(
        '.ds-attachment-tile__remove',
      );
      const next = buttons?.[Math.min(index, (buttons?.length ?? 0) - 1)];
      if (next) next.focus();
      else textareaRef.current?.focus();
    }, [files]);

    const handleFileRemove = (id: string, index: number) => {
      focusAfterRemove.current = index;
      onFileRemove?.(id);
    };

    const handlePick = (event: React.ChangeEvent<HTMLInputElement>) => {
      const picked = Array.from(event.target.files ?? []);
      // Reset so picking the same file again still fires a change
      event.target.value = '';
      if (picked.length > 0) onFilesSelected?.(picked);
    };

    const handlePaste = (event: React.ClipboardEvent<HTMLTextAreaElement>) => {
      onPaste?.(event);
      if (event.defaultPrevented) return;
      const pasted = Array.from(event.clipboardData?.files ?? []);
      if (armed && pasted.length > 0) {
        event.preventDefault();
        onFilesSelected?.(pasted);
        return;
      }
      if (pasteThreshold === undefined || !onPasteAsAttachment) return;
      const text = event.clipboardData?.getData('text/plain') ?? '';
      if (text.length >= pasteThreshold) {
        event.preventDefault();
        onPasteAsAttachment(text);
      }
    };

    /* Drop on the shell. A drag that carries files is taken here and goes
       no further, so a drop target around the composer (a page-level one,
       say) does not handle the same files a second time. */
    const takesDrag = (event: React.DragEvent) => armed && !disabled && dragCarriesFiles(event);

    const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
      if (!takesDrag(event)) return;
      event.preventDefault();
      event.stopPropagation();
      dragDepth.current += 1;
      setDragging(true);
    };

    const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
      if (!takesDrag(event)) return;
      // Without this the browser refuses the drop and opens the file instead
      event.preventDefault();
      event.stopPropagation();
      event.dataTransfer.dropEffect = 'copy';
    };

    const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
      if (!takesDrag(event)) return;
      event.stopPropagation();
      dragDepth.current = Math.max(0, dragDepth.current - 1);
      if (dragDepth.current === 0) setDragging(false);
    };

    const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
      if (!takesDrag(event)) return;
      event.preventDefault();
      event.stopPropagation();
      dragDepth.current = 0;
      setDragging(false);
      const dropped = Array.from(event.dataTransfer.files ?? []);
      if (dropped.length > 0) onFilesSelected?.(dropped);
    };

    const submit = () => {
      if (streaming || !canSend) return;
      onSubmit?.(currentValue);
    };

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      if (!isControlled) setUncontrolledValue(e.target.value);
      onChange?.(e);
      onValueChange?.(e.target.value);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      onKeyDown?.(e);
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        // Inert while streaming or trimmed-empty — submit() guards both.
        submit();
      }
    };

    /* The whole shell is the input affordance: clicking anywhere that is not
       a control focuses the textarea, so the click target is the visible
       shape rather than the text line inside it. */
    const handleShellClick = (e: React.MouseEvent<HTMLDivElement>) => {
      const target = e.target as HTMLElement;
      if (target.closest('button, a, textarea, input, select, [role="button"]')) return;
      textareaRef.current?.focus();
    };

    const classes = [
      baseClass,
      aiGlow ? `${baseClass}--ai-glow` : '',
      streaming ? `${baseClass}--streaming` : '',
      disabled ? `${baseClass}--disabled` : '',
      dragging ? `${baseClass}--dragging` : '',
      // The above placement moves the text onto the chip's rail; the shell
      // needs to know, since the chip is no longer inside it.
      context && contextPlacement === 'above' ? `${baseClass}--context-above` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    // The textarea needs an accessible name; default one in when the caller
    // provides neither aria-label nor aria-labelledby.
    const ariaLabel =
      rest['aria-label'] ?? (rest['aria-labelledby'] !== undefined ? undefined : 'Message');

    /* One chip, placed by contextPlacement: inside the shell, where the
       shell's click handler already covers it, or above it as a sibling bar
       carrying the same handler, so a click still focuses the textarea. */
    const contextAbove = contextPlacement === 'above';
    const contextChip = context ? (
      <div
        className={`${baseClass}__context${contextAbove ? ` ${baseClass}__context--above` : ''}`}
        onClick={contextAbove ? handleShellClick : undefined}
      >
        {contextIcon && (
          <span className={`${baseClass}__context-icon`} aria-hidden="true">
            {typeof contextIcon === 'string' ? (
              <span className="material-symbols-rounded">{contextIcon}</span>
            ) : (
              contextIcon
            )}
          </span>
        )}
        <span className={`${baseClass}__context-text`}>{context}</span>
      </div>
    ) : null;

    const shell = (
      <div
        className={classes}
        style={{ '--ds-composer-max-rows': maxRows } as React.CSSProperties}
        onClick={handleShellClick}
        onDragEnter={armed ? handleDragEnter : undefined}
        onDragOver={armed ? handleDragOver : undefined}
        onDragLeave={armed ? handleDragLeave : undefined}
        onDrop={armed ? handleDrop : undefined}
      >
        {!contextAbove && contextChip}

        {hasFiles && (
          <ul className={`${baseClass}__tray`} ref={trayRef} aria-label={filesLabel}>
            {queued.map((file, index) => (
              <li key={file.id} className={`${baseClass}__tray-item`}>
                <AttachmentTile
                  name={file.name}
                  kind={file.kind}
                  status={file.status}
                  progress={file.progress}
                  error={file.error}
                  previewSrc={file.previewSrc}
                  previewAlt={file.previewAlt}
                  excerpt={file.excerpt}
                  meta={file.size === undefined ? undefined : formatBytes(file.size)}
                  onClick={onFileClick ? () => onFileClick(file) : undefined}
                  onRemove={
                    onFileRemove && !disabled ? () => handleFileRemove(file.id, index) : undefined
                  }
                />
              </li>
            ))}
          </ul>
        )}

        {attachments && <div className={`${baseClass}__attachments`}>{attachments}</div>}

        <div className={`${baseClass}__content`} ref={contentRef}>
          <textarea
            {...rest}
            ref={setTextareaRef}
            className={`${baseClass}__textarea`}
            rows={1}
            value={currentValue}
            aria-label={ariaLabel}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            onPaste={handlePaste}
          />
        </div>

        <div className={`${baseClass}__footer`}>
          {(actions || (armed && attachButton)) && (
            <div className={`${baseClass}__actions`}>
              {armed && attachButton && (
                <CircularButton
                  icon="add"
                  variant="tertiary"
                  ariaLabel={attachLabel}
                  disabled={disabled}
                  onClick={() => fileInputRef.current?.click()}
                />
              )}
              {actions}
            </div>
          )}
          <div className={`${baseClass}__trailing`}>
            {trailingActions}
            {streaming ? (
              <CircularButton
                icon="stop"
                variant="primary"
                ariaLabel={stopLabel}
                disabled={disabled}
                onClick={onStop}
              />
            ) : (
              <CircularButton
                icon="arrow_upward"
                variant="primary"
                ariaLabel={sendLabel}
                disabled={!canSend}
                onClick={submit}
              />
            )}
          </div>
        </div>

        {armed && (
          <>
            {/* The picker behind the attach button. Out of the tab order and
                the accessibility tree: the button is the control. */}
            <input
              ref={fileInputRef}
              className={`${baseClass}__file-input`}
              type="file"
              accept={accept}
              multiple={multiple}
              tabIndex={-1}
              aria-hidden="true"
              onChange={handlePick}
            />
            {/* Decorative: the words describe a pointer gesture in progress */}
            <div className={`${baseClass}__drop-hint`} aria-hidden="true">
              {dropLabel}
            </div>
          </>
        )}

        {(armed || hasFiles) && (
          <span className={`${baseClass}__sr-only`} role="status">
            {announcement}
          </span>
        )}
      </div>
    );

    /* Above the shell, the bar and the shell travel as one block in a
       wrapper, so a host's own flex or grid gap can never land between
       them. The wrapper is plain layout; `className` stays on the shell. */
    if (contextAbove && contextChip) {
      return (
        <div className={`${baseClass}-group`}>
          {contextChip}
          {shell}
        </div>
      );
    }

    return shell;
  },
);

Composer.displayName = 'Composer';
